/**
 * WEB GIRIS - CANLI UCTAN UCA TEST (2026-09-14)
 *
 * slooin.com/giris sayfasindan gercek bir hesapla giris yapip oturumun
 * uygulamanin web surumune (slooin.expo.app) gectigini olcer. Jest bu
 * akisi goremez: iki ayri alan adi, gercek Supabase, gercek tarayici.
 *
 *   node araclar/giris-canli-test.mjs
 *
 * Hesap: Beta App Review icin acilmis demo hesap (test0@slooin.test).
 * Parola bu dosyada DEGIL; SLOOIN_TEST_SIFRE ortam degiskeninden ya da
 * mobil/.env icindeki ayni adli satirdan okunur.
 *
 * Olculenler:
 *   1. yanlis parola -> sayfa ayni kalir, hata metni gorunur
 *   2. dogru parola  -> slooin.expo.app'e gecis
 *   3. adres cubugunda jeton KALMAZ (supabase-js fragment'i temizler)
 *   4. uygulama oturumu localStorage'a yazmistir
 *   5. uygulama giris ekranini DEGIL ana ekrani gosterir
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const BURASI = path.dirname(fileURLToPath(import.meta.url))
const CHROME =
  process.env.SLOOIN_CHROME || 'C:/Program Files/Google/Chrome/Application/chrome.exe'
const PUPPETEER_YOLU =
  process.env.SLOOIN_PUPPETEER ||
  'file:///C:/Users/orcns/projects/cloud/mobil/node_modules/puppeteer-core/lib/puppeteer/puppeteer-core.js'
const GIRIS = process.env.SLOOIN_GIRIS_URL || 'https://slooin.com/giris/'
const UYGULAMA = 'https://slooin.expo.app/'
const EPOSTA = process.env.SLOOIN_TEST_EPOSTA || 'test0@slooin.test'

function envdenOku(ad) {
  if (process.env[ad]) return process.env[ad]
  const env = path.join(BURASI, '..', '..', 'mobil', '.env')
  if (!fs.existsSync(env)) return undefined
  const satir = fs
    .readFileSync(env, 'utf8')
    .split(/\r?\n/)
    .find((s) => s.startsWith(ad + '='))
  return satir ? satir.slice(ad.length + 1).trim().replace(/^["']|["']$/g, '') : undefined
}
const SIFRE = envdenOku('SLOOIN_TEST_SIFRE')
if (!SIFRE) {
  console.error('SLOOIN_TEST_SIFRE tanimsiz (ortam ya da mobil/.env).')
  process.exit(2)
}

const puppeteer = (await import(PUPPETEER_YOLU)).default
let gecen = 0
let kalan = 0
function kontrol(kosul, ad, ek = '') {
  if (kosul) gecen++
  else kalan++
  console.log(`  ${kosul ? 'GECTI ' : 'KALDI '} ${ad}${ek ? '  (' + ek + ')' : ''}`)
}

const tarayici = await puppeteer.launch({
  executablePath: CHROME,
  headless: 'new',
  args: ['--no-sandbox'],
})
try {
  const sayfa = await tarayici.newPage()
  await sayfa.setViewport({ width: 420, height: 860 })

  // 1. Yanlis parola
  await sayfa.goto(GIRIS, { waitUntil: 'networkidle0' })
  await sayfa.type('input[name=eposta]', EPOSTA)
  await sayfa.type('input[name=sifre]', 'yanlis-parola-000')
  await sayfa.click('#giris-dugmesi')
  await sayfa.waitForFunction(
    () => /hatal|wrong|falsch|incorrect|неверн|خاطئ/i.test(document.getElementById('durum')?.textContent || ''),
    { timeout: 15000 },
  )
  const hataMetni = await sayfa.$eval('#durum', (e) => e.textContent)
  kontrol(sayfa.url().startsWith(GIRIS), 'yanlis parolada sayfa ayni kalir', sayfa.url())
  kontrol(/hatal/i.test(hataMetni), 'yanlis parolada hata metni gorunur', hataMetni)
  const dugmeAcik = await sayfa.$eval('#giris-dugmesi', (b) => !b.disabled)
  kontrol(dugmeAcik, 'hatadan sonra dugme yeniden aktif')

  // 2. Dogru parola -> uygulamaya gecis
  await sayfa.$eval('input[name=sifre]', (i) => (i.value = ''))
  await sayfa.type('input[name=sifre]', SIFRE)
  await Promise.all([
    sayfa.waitForNavigation({ waitUntil: 'networkidle0', timeout: 60000 }),
    sayfa.click('#giris-dugmesi'),
  ])
  // Uygulama acilip fragment'i temizleyene kadar bekle.
  await sayfa.waitForFunction(() => !location.hash.includes('access_token'), { timeout: 30000 })
  const son = sayfa.url()
  kontrol(son.startsWith(UYGULAMA), 'dogru parolada slooin.expo.app acilir', son)
  kontrol(!son.includes('access_token') && !son.includes('refresh_token'), 'adres cubugunda jeton kalmaz')

  // 3. Oturum uygulamada
  const oturum = await sayfa.evaluate(() => {
    const k = Object.keys(localStorage).find((k) => /auth-token/.test(k))
    if (!k) return null
    try {
      const v = JSON.parse(localStorage.getItem(k))
      return { anahtar: k, eposta: v?.user?.email || null, jeton: !!v?.access_token }
    } catch {
      return { anahtar: k, eposta: null, jeton: false }
    }
  })
  kontrol(!!oturum && oturum.jeton, 'oturum localStorage\'a yazilmis', oturum ? oturum.anahtar : 'yok')
  kontrol(oturum?.eposta === EPOSTA, 'oturum dogru hesaba ait', oturum?.eposta || '-')

  // 4. Ekran giris degil ana ekran
  await sayfa.waitForFunction(() => document.body.innerText.length > 40, { timeout: 30000 })
  await new Promise((c) => setTimeout(c, 2500))
  const metin = await sayfa.evaluate(() => document.body.innerText)
  const girisEkrani = /Giriş yap|Hesabın yok mu|Sign in/.test(metin) && !/Profil/.test(metin)
  kontrol(!girisEkrani, 'uygulama giris ekrani DEGIL ana ekrani gosterir', metin.slice(0, 80).replace(/\s+/g, ' '))
  kontrol(/Profil/.test(metin), 'alt gezinmede Profil sekmesi var')

  const png = path.join(BURASI, '..', '..', 'tasarim', 'web-giris-sonuc.png')
  await sayfa.screenshot({ path: png })
  console.log('  ekran goruntusu:', png)

  // Temizlik: uygulamada cikis (oturum kayitlari birikmesin).
  await sayfa.evaluate(() => localStorage.clear())
} finally {
  await tarayici.close()
}

console.log(`\n${gecen} gecti, ${kalan} kaldi`)
process.exit(kalan ? 1 : 0)

