  kontrol(son.startsWith(UYGULAMA), 'dogru parolada slooin.expo.app acilir', son)
  kontrol(!son.includes('access_token') && !son.includes('refresh_token'), 'adres cubugunda jeton kalmaz')

  // 3. Oturum uygulamada
  const oturum = await sayfa.evaluate(() => {
    const k = Object.keys(localStorage).find((k) => /auth-token/.test(k))
    if (!k) return null
    try {
      const v = JSON.parse(localStorage.getItem(k))
      return { anahtar: k, eposta: v?.user?.email || null, jeton: !!v?.access_token }
    } catch {
      return { anahtar: k, eposta: null, jeton: false }
    }
  })
  kontrol(!!oturum && oturum.jeton, 'oturum localStorage\'a yazilmis', oturum ? oturum.anahtar : 'yok')
  kontrol(oturum?.eposta === EPOSTA, 'oturum dogru hesaba ait', oturum?.eposta || '-')

  // 4. Ekran giris degil ana ekran
  await sayfa.waitForFunction(() => document.body.innerText.length > 40, { timeout: 30000 })
  await new Promise((c) => setTimeout(c, 2500))
  const metin = await sayfa.evaluate(() => document.body.innerText)
  const girisEkrani = /Giriş yap|Hesabın yok mu|Sign in/.test(metin) && !/Profil/.test(metin)
  kontrol(!girisEkrani, 'uygulama giris ekrani DEGIL ana ekrani gosterir', metin.slice(0, 80).replace(/\s+/g, ' '))
  kontrol(/Profil/.test(metin), 'alt gezinmede Profil sekmesi var')

  const png = path.join(BURASI, '..', '..', 'tasarim', 'web-giris-sonuc.png')
  await sayfa.screenshot({ path: png })
  console.log('  ekran goruntusu:', png)

  // Temizlik: uygulamada cikis (oturum kayitlari birikmesin).
  await sayfa.evaluate(() => localStorage.clear())
} finally {
  await tarayici.close()
}

console.log(`\n${gecen} gecti, ${kalan} kaldi`)
process.exit(kalan ? 1 : 0)

