import { Modal, Pressable, StyleSheet, Text, View } from 'react-native'
import { useDil } from '../../lib/dil'
import { bosluk, olcek, yazi, yuvarlak, type Renk } from './tema'
import { useStiller } from './tema-baglami'

/**
 * SECENEK PENCERESI - bir satirin "..." dugmesinden acilan kisa liste.
 *
 * Ilk kullanim (2026-09-14): profildeki arkadas listesi, "Arkadasliktan
 * cikar" / "Engelle". `OnayPenceresi` ile ayni gorunum (ortada kart,
 * karartma, ayiracli dugmeler, en altta Vazgec) - ayni sey her ekranda
 * ayni gorunsun. `Alert`/ActionSheet DEGIL: web'de calismiyor ve uc
 * platformda farkli gorunuyor (OnayPenceresi'ndeki gerekce).
 */
export type Secenek = {
  etiket: string
  onSec: () => void
  /** Yikici secenek kirmizi; digerleri metin renginde. */
  yikici?: boolean
  testID?: string
}

export function SecenekPenceresi({
  acikMi,
  baslik,
  secenekler,
  onVazgec,
}: {
  acikMi: boolean
  /** Istege bagli: kimin icin secildigini soyleyen kisa baslik (ad). */
  baslik?: string
  secenekler: Secenek[]
  onVazgec: () => void
}) {
  const stiller = useStiller(stilleriYap)
  const { t } = useDil()
  if (!acikMi) return null
  return (
    <Modal visible transparent animationType="fade" onRequestClose={onVazgec}>
      <Pressable style={stiller.zemin} testID="secenek-zemini" onPress={onVazgec}>
        <Pressable style={stiller.pencere} testID="secenek-penceresi" onPress={() => {}} accessibilityViewIsModal>
          {baslik ? (
            <View style={stiller.baslikAlani}>
              <Text style={stiller.baslik} numberOfLines={1}>
                {baslik}
              </Text>
            </View>
          ) : null}
          {secenekler.map((s) => (
            <View key={s.etiket}>
              <View style={stiller.ayirac} />
              <Pressable style={stiller.dugme} onPress={s.onSec} accessibilityRole="button" testID={s.testID}>
                <Text style={[stiller.dugmeYazi, s.yikici ? stiller.yikici : stiller.normal]}>{s.etiket}</Text>
              </Pressable>
            </View>
          ))}
          <View style={stiller.ayirac} />
          <Pressable style={stiller.dugme} onPress={onVazgec} accessibilityRole="button">
            <Text style={[stiller.dugmeYazi, stiller.vazgec]}>{t('ortak.vazgec')}</Text>
          </Pressable>
        </Pressable>
      </Pressable>
    </Modal>
  )
}

