                  <Text style={[stiller.rozetYazi, { color: DURUM_RENGI[d] }]}>
                    {t(`kesfet.${d}`)}
                  </Text>
                </View>

                <Pressable
                  style={({ pressed }) => [
                    stiller.kartCheckIn,
                    pressed && stiller.kartCheckInBasili,
