          kaynagi yazmak zaten gerekli. */}
      <Text style={stiller.atif}>{t('kesfet.atif')}</Text>
    </ScrollView>

    <TurSecici
      acikMi={turSeciciAcik}
      gruplar={TEMEL_TUR_GRUPLARI}
      adetler={yakinTurler}
      yukleniyor={turlerYukleniyor}
      secili={seciliTurler}
      onKapat={() => setTurSeciciAcik(false)}
      onKaydet={turleriUygula}
    />

    </View>
  )
}

