"""SLOOIN PROJESI - HICBIR SEY DISARIDA KALMADAN tek ZIP.

Icerik: proje klasorunun TAMAMI (kod, .git gecmisi, node_modules,
derleme ciktilari, gorseller, veri dosyalari, oturum dokumleri, .env ve
.p8 sirlari), makineye bagli otomatik hafiza klasoru, masaustundeki
tek-dosya Markdown dokumu ve kisayol. ZIP64 - 4 GB siniri yok.
"""
import os, sys, zipfile, time

KOK = 'C:/Users/orcns/projects/cloud'
EKLER = {
    'hafiza': 'C:/Users/orcns/.claude/projects/C--Users-orcns-projects-cloud/memory',
}
TEKIL = [
    'C:/Users/orcns/Desktop/slooin projesi.md',
    'C:/Users/orcns/Desktop/Claude - cloud projesi.bat',
]
CIKTI = sys.argv[1]

basla = time.time()
sayac = 0
bayt = 0
with zipfile.ZipFile(CIKTI, 'w', compression=zipfile.ZIP_DEFLATED, compresslevel=5, allowZip64=True) as z:
    def ekle(tam, arsivYolu):
        global sayac, bayt
        try:
            z.write(tam, arsivYolu)
            sayac += 1
            bayt += os.path.getsize(tam)
        except (PermissionError, OSError) as e:
            print('ATLANDI', arsivYolu, e, flush=True)

    for kokDizin, dizinler, dosyalar in os.walk(KOK):
        for ad in dosyalar:
            tam = os.path.join(kokDizin, ad)
            ekle(tam, 'slooin-projesi/' + os.path.relpath(tam, KOK).replace('\\', '/'))
        if sayac and sayac % 20000 < len(dosyalar):
            print(f'{sayac} dosya, {bayt // 1048576} MB, {int(time.time() - basla)} sn', flush=True)
    for ad, dizin in EKLER.items():
        for kokDizin, _, dosyalar in os.walk(dizin):
            for d in dosyalar:
                tam = os.path.join(kokDizin, d)
                ekle(tam, f'{ad}/' + os.path.relpath(tam, dizin).replace('\\', '/'))
    for tam in TEKIL:
        if os.path.exists(tam):
            ekle(tam, 'masaustu/' + os.path.basename(tam))

print(f'BITTI: {sayac} dosya, {bayt // 1048576} MB ham, zip {os.path.getsize(CIKTI) // 1048576} MB, {int(time.time() - basla)} sn')

